package com.powerliq.publisher;
import java.net.URI;import java.time.Duration;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.annotation.Bean;import org.springframework.scheduling.annotation.EnableScheduling;import software.amazon.awssdk.auth.credentials.AwsBasicCredentials;import software.amazon.awssdk.auth.credentials.DefaultCredentialsProvider;import software.amazon.awssdk.auth.credentials.StaticCredentialsProvider;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.eventbridge.EventBridgeClient;
@AutoConfiguration
@EnableScheduling
@ConditionalOnProperty(name="powerliq.events.publisher.enabled",havingValue="true")
public class EventPublisherAutoConfiguration{
 @Bean @ConditionalOnMissingBean EventBridgeClient eventBridge(@Value("${powerliq.aws.region:eu-west-2}")String region,@Value("${powerliq.events.endpoint:}")String endpoint){var builder=EventBridgeClient.builder().region(Region.of(region)).credentialsProvider(DefaultCredentialsProvider.create()).overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(5)).apiCallAttemptTimeout(Duration.ofSeconds(3)));if(!endpoint.isBlank())builder.endpointOverride(URI.create(endpoint)).credentialsProvider(StaticCredentialsProvider.create(AwsBasicCredentials.create("local","local")));return builder.build();}
 @Bean OutboxEventPublisher publisher(org.springframework.jdbc.core.JdbcTemplate jdbc,org.springframework.transaction.PlatformTransactionManager tx,EventBridgeClient client,@Value("${powerliq.events.bus-name}")String bus,@Value("${powerliq.events.table:outbox_events}")String table,@Value("${spring.application.name}")String source,@Value("${powerliq.events.publisher-batch-size:10}")int batchSize,@Value("${powerliq.events.max-attempts:10}")int maxAttempts){return new OutboxEventPublisher(jdbc,tx,client,bus,table,source,batchSize,maxAttempts);}
}
